import axios from "axios";

import {
  WeatherRecord,
  WeatherSummaryData,
  WeatherOutlookDay,
  WeatherSignalsData,
} from "../types/weather.types";

class WeatherService {
  private readonly baseUrl = "/api";

  /**
   * Get the complete weather time series
   * for the selected forecast entity.
   */
  async getWeatherData(
    entityId: string
  ): Promise<WeatherRecord[]> {
    const response =
      await axios.get<WeatherRecord[]>(
        `${this.baseUrl}/weather-data`,
        {
          params: {
            entity_id: entityId,
          },
        }
      );

    return Array.isArray(response.data)
      ? response.data
      : [];
  }

  /**
   * Sort weather records chronologically.
   */
  private sortRecords(
    records: WeatherRecord[]
  ): WeatherRecord[] {
    return [...records].sort(
      (a, b) =>
        new Date(a.date).getTime() -
        new Date(b.date).getTime()
    );
  }

  /**
   * Get the latest available weather observation.
   */
  async getWeatherSummary(
    entityId: string
  ): Promise<WeatherSummaryData | null> {
    const records =
      await this.getWeatherData(
        entityId
      );

    if (
      !records ||
      records.length === 0
    ) {
      return null;
    }

    const sorted =
      this.sortRecords(records);

    const latest =
      sorted[sorted.length - 1];

    return this.mapRecordToSummary(
      entityId,
      latest
    );
  }

  /**
   * Get the weather outlook.
   *
   * We do NOT create fake data.
   *
   * If the backend provides 7 days,
   * the UI gets 7 days.
   *
   * If the backend provides 30 days,
   * the UI gets 30 days.
   */
  async getWeatherOutlook(
    entityId: string,
    days: number
  ): Promise<WeatherOutlookDay[]> {
    const records =
      await this.getWeatherData(
        entityId
      );

    if (
      !records ||
      records.length === 0
    ) {
      return [];
    }

    const sorted =
      this.sortRecords(records);

    return sorted
      .slice(0, days)
      .map((record) =>
        this.mapRecordToOutlook(
          record
        )
      );
  }

  /**
   * Calculate aggregated weather
   * signals from the available outlook.
   */
  async getWeatherSignals(
    entityId: string,
    days: number
  ): Promise<WeatherSignalsData> {
    const outlook =
      await this.getWeatherOutlook(
        entityId,
        days
      );

    if (outlook.length === 0) {
      return {
        forecastDays: 0,
        averageTemperature: null,
        totalRainfall: null,
        averageWindSpeed: null,
        averageUvIndex: null,
        averageHumidity: null,
        rainyDays: 0,
        hotDays: 0,
      };
    }

    const temperatures =
      outlook
        .filter(
          (record) =>
            record.tempMax !== null
        )
        .map(
          (record) =>
            record.tempMax as number
        );

    const rainfall =
      outlook
        .filter(
          (record) =>
            record.rainfall !== null
        )
        .map(
          (record) =>
            record.rainfall as number
        );

    const wind =
      outlook
        .filter(
          (record) =>
            record.windSpeed !== null
        )
        .map(
          (record) =>
            record.windSpeed as number
        );

    const uv =
      outlook
        .filter(
          (record) =>
            record.uvIndex !== null
        )
        .map(
          (record) =>
            record.uvIndex as number
        );

    const humidity =
      outlook
        .filter(
          (record) =>
            record.humidity !== null
        )
        .map(
          (record) =>
            record.humidity as number
        );

    const average = (
      values: number[]
    ): number | null => {
      if (values.length === 0) {
        return null;
      }

      return (
        values.reduce(
          (
            total: number,
            value: number
          ) => total + value,
          0
        ) / values.length
      );
    };

    const total = (
      values: number[]
    ): number | null => {
      if (values.length === 0) {
        return null;
      }

      return values.reduce(
        (
          sum: number,
          value: number
        ) => sum + value,
        0
      );
    };

    return {
      forecastDays:
        outlook.length,

      averageTemperature:
        average(
          temperatures
        ),

      totalRainfall:
        total(rainfall),

      averageWindSpeed:
        average(wind),

      averageUvIndex:
        average(uv),

      averageHumidity:
        average(humidity),

      rainyDays:
        outlook.filter(
          (record) =>
            (record.rainfall ?? 0) >
            0.1
        ).length,

      hotDays:
        outlook.filter(
          (record) =>
            (record.tempMax ?? 0) >=
            25
        ).length,
    };
  }

  private mapRecordToSummary(
    entityId: string,
    record: WeatherRecord
  ): WeatherSummaryData {
    return {
      entityId,

      date: record.date,

      condition:
        record.weather_label ??
        "Unknown",

      tempMax:
        this.toNumber(
          record.temp_max_c
        ),

      tempMin:
        this.toNumber(
          record.temp_min_c
        ),

      rainfall:
        this.toNumber(
          record.rainfall_mm
        ),

      cloudCover:
        this.toNumber(
          record.cloud_cover_pct
        ),

      humidity:
        this.toNumber(
          record.humidity_pct
        ),

      windSpeed:
        this.toNumber(
          record.wind_speed_kmh
        ),

      uvIndex:
        this.toNumber(
          record.uv_index
        ),

      sunshine:
        this.toHours(
          record.sunshine_seconds
        ),
    };
  }

  private mapRecordToOutlook(
    record: WeatherRecord
  ): WeatherOutlookDay {
    return {
      date: record.date,

      condition:
        record.weather_label ??
        "Unknown",

      tempMax:
        this.toNumber(
          record.temp_max_c
        ),

      tempMin:
        this.toNumber(
          record.temp_min_c
        ),

      rainfall:
        this.toNumber(
          record.rainfall_mm
        ),

      cloudCover:
        this.toNumber(
          record.cloud_cover_pct
        ),

      humidity:
        this.toNumber(
          record.humidity_pct
        ),

      windSpeed:
        this.toNumber(
          record.wind_speed_kmh
        ),

      uvIndex:
        this.toNumber(
          record.uv_index
        ),

      sunshine:
        this.toHours(
          record.sunshine_seconds
        ),
    };
  }

  private toNumber(
    value:
      | number
      | null
      | undefined
  ): number | null {
    if (
      value === null ||
      value === undefined
    ) {
      return null;
    }

    const number =
      Number(value);

    return Number.isFinite(number)
      ? number
      : null;
  }

  private toHours(
    value:
      | number
      | null
      | undefined
  ): number | null {
    if (
      value === null ||
      value === undefined
    ) {
      return null;
    }

    const seconds =
      Number(value);

    if (
      !Number.isFinite(seconds)
    ) {
      return null;
    }

    return seconds / 3600;
  }
}

const weatherService =
  new WeatherService();

export default weatherService;
